{"cards": [{"node_code": "N_0b48ca7722521a30", "definition": "研究铁路专用有线通信系统的技术体系，涵盖电话、传真、数据电路等基于物理介质（如电缆、光纤）的信息传输技术、网络架构及设备工程。", "boundary": "本节点聚焦于“有线”传输介质。边界在于区分“有线”与“无线”：依赖导线、光纤等物理连接传输信号归本节点；依赖电磁波在空间传播归无线通信。若内容涉及通信网整体拓扑设计，归铁路通信网；若涉及具体设备维护，归保养与检修。", "includes": ["铁路有线电话、传真及专用数据通信电路技术", "铁路通信电缆、光缆的敷设、特性及工程应用", "有线通信交换设备、传输设备及其在铁路场景的应用"], "excludes": ["基于无线电波、微波或卫星的无线通信内容", "通信系统的纯数学理论或通用控制理论", "非铁路专用的通用电信网络内容"], "sibling_distinctions": [{"other_code": "N_509476a9eb515e68", "rule": "区分依据为传输介质：有线通信依赖电缆、光纤等物理介质；无线通信依赖电磁波在自由空间传播。"}, {"other_code": "N_403b38ca0f96eaf5", "rule": "区分依据为内容侧重：有线通信侧重物理层传输技术与介质；铁路数据通信侧重数据协议、网络架构及业务应用，可能涵盖有线与无线多种承载方式。"}], "cross_boundary_rule": "若内容涉及“光纤通信”，若侧重光纤物理特性、线路工程及有线传输技术，主挂载本节点；若侧重基于光纤的数据网络协议或业务应用，可关联铁路数据通信。"}, {"node_code": "N_509476a9eb515e68", "definition": "研究铁路专用无线通信系统的技术体系，涵盖列调、GSM-R、微波、卫星等基于电磁波传输的通信手段、网络架构及设备工程。", "boundary": "本节点聚焦于“无线”传输介质。边界在于区分“无线”与“有线”：依赖电磁波在空间传播归本节点；依赖物理介质归有线通信。若内容涉及无线通信与信号控制的结合（如GSM-R信号部分），侧重通信网络归本节点，侧重控制逻辑归铁路信号。", "includes": ["铁路列车调度无线通信（列调）、GSM-R系统技术", "铁路微波、卫星通信及无线数据通信网络", "无线通信基站、车载电台等设备及工程应用"], "excludes": ["基于电缆、光纤等物理介质的有线通信内容", "非铁路专用的通用移动通信技术", "无线通信系统的纯数学理论或通用控制理论"], "sibling_distinctions": [{"other_code": "N_0b48ca7722521a30", "rule": "区分依据为传输介质：无线通信依赖电磁波在自由空间传播；有线通信依赖电缆、光纤等物理介质。"}, {"other_code": "N_403b38ca0f96eaf5", "rule": "区分依据为内容侧重：无线通信侧重无线传输技术与设备；铁路数据通信侧重数据协议、网络架构及业务应用，可能涵盖无线承载。"}], "cross_boundary_rule": "若内容涉及“GSM-R”，若侧重无线接入网、基站技术、无线传输特性，主挂载本节点；若侧重基于GSM-R的信号控制逻辑或核心网数据业务，可关联铁路信号或铁路数据通信。"}, {"node_code": "N_89fba41f7dbd2ff4", "definition": "研究电视技术在铁路领域的具体应用，涵盖视频监控、图像传输、显示终端及相关的系统集成、工程实施与维护管理。", "boundary": "本节点聚焦于“电视/视频”这一特定应用形态。边界在于区分“应用”与“通用技术”：侧重铁路场景下的视频采集、传输、显示及监控业务归本节点；通用电视技术原理归通信理论或通用电子类。若涉及视频传输的底层通信协议，可关联铁路数据通信，但应用层归本节点。", "includes": ["铁路车站、区间、车辆的视频监控系统及图像传输技术", "铁路电视会议、信息显示终端及多媒体应用", "铁路视频通信系统的集成、工程实施及维护"], "excludes": ["非铁路专用的通用广播电视技术", "视频信号的纯数学处理算法或通用图像处理理论", "不涉及视频内容的纯语音或数据通信内容"], "sibling_distinctions": [{"other_code": "N_403b38ca0f96eaf5", "rule": "区分依据为业务类型：电视应用侧重视频/图像业务的采集、显示与监控；铁路数据通信侧重通用数据协议、网络架构及非视频类数据业务。"}, {"other_code": "N_0b48ca7722521a30", "rule": "区分依据为内容层级：电视应用侧重视频业务在铁路场景的具体实现；有线通信侧重物理传输介质与底层传输技术，视频可基于有线传输，但应用层归本节点。"}], "cross_boundary_rule": "若内容涉及“视频监控系统”，若侧重摄像头、显示终端、监控业务逻辑及铁路场景集成，主挂载本节点；若侧重视频流在通信网络中的传输协议、带宽优化或底层有线/无线传输技术，可关联铁路数据通信或有线/无线通信。"}]}
